import React, { useState } from 'react';
import { User, Briefcase, Upload, CheckCircle, X } from 'lucide-react';

const Register = () => {
  const [showModal, setShowModal] = useState(null); // 'student' or 'hr'
  const [isVerified, setIsVerified] = useState(false);

  const handleVerify = (e) => {
    e.preventDefault();
    // Simulate verification logic
    setIsVerified(true);
    setTimeout(() => {
      alert("Verification Submitted Successfully!");
      setShowModal(null);
      setIsVerified(false);
    }, 1500);
  };

  return (
    <div className="min-h-screen bg-[#f3f4f9] flex flex-col items-center justify-center p-6">
      <h1 className="text-3xl font-bold text-gray-800 mb-8">Join the Talent Pool</h1>
      
      {/* The Oval Toggle from your sketch */}
      <div className="bg-white p-2 rounded-full shadow-lg flex border-2 border-purple-100 w-full max-w-md">
        <button 
          onClick={() => setShowModal('student')}
          className="flex-1 flex items-center justify-center gap-3 py-4 rounded-full hover:bg-purple-50 transition-all group"
        >
          <div className="bg-purple-100 p-2 rounded-full group-hover:bg-purple-600 group-hover:text-white transition-colors">
            <User size={24} />
          </div>
          <span className="font-bold text-gray-700">Student</span>
        </button>

        <div className="w-[2px] bg-gray-100 my-2"></div>

        <button 
          onClick={() => setShowModal('hr')}
          className="flex-1 flex items-center justify-center gap-3 py-4 rounded-full hover:bg-blue-50 transition-all group"
        >
          <div className="bg-blue-100 p-2 rounded-full group-hover:bg-blue-600 group-hover:text-white transition-colors">
            <Briefcase size={24} />
          </div>
          <span className="font-bold text-gray-700">HR / Admin</span>
        </button>
      </div>

      <p className="mt-6 text-gray-500 italic">Select your role to continue registration</p>

      {/* --- REGISTRATION MODAL --- */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden relative animate-in fade-in zoom-in duration-300">
            
            {/* Modal Header */}
            <div className={`p-6 text-white flex justify-between items-center ${showModal === 'student' ? 'bg-[#7c5dfa]' : 'bg-blue-600'}`}>
              <h2 className="text-xl font-bold">
                {showModal === 'student' ? 'Student Registration' : 'HR & Company Details'}
              </h2>
              <button onClick={() => setShowModal(null)}><X size={24} /></button>
            </div>

            <form onSubmit={handleVerify} className="p-8 space-y-4 max-h-[70vh] overflow-y-auto">
              {showModal === 'student' ? (
                <>
                  {/* Student Specific Fields */}
                  <input type="text" placeholder="Full Name" className="w-full p-3 border rounded-xl" required />
                  <input type="text" placeholder="University/College" className="w-full p-3 border rounded-xl" required />
                  <div className="border-2 border-dashed border-purple-200 p-6 rounded-2xl text-center">
                    <Upload className="mx-auto text-purple-400 mb-2" />
                    <p className="text-sm text-gray-500">Upload Certificates (PDF/PNG)</p>
                    <input type="file" className="mt-2 text-xs" required />
                  </div>
                </>
              ) : (
                <>
                  {/* HR Specific Fields */}
                  <input type="text" placeholder="Company Name" className="w-full p-3 border rounded-xl" required />
                  <input type="text" placeholder="Job Role Selection" className="w-full p-3 border rounded-xl" required />
                  <textarea placeholder="Required Skills" className="w-full p-3 border rounded-xl" rows="3"></textarea>
                  <div className="border-2 border-dashed border-blue-200 p-6 rounded-2xl text-center">
                    <Upload className="mx-auto text-blue-400 mb-2" />
                    <p className="text-sm text-gray-500">Upload Company ID/Verification</p>
                    <input type="file" className="mt-2 text-xs" required />
                  </div>
                </>
              )}

              {/* Verification Button */}
              <button 
                type="submit"
                disabled={isVerified}
                className={`w-full py-4 rounded-xl font-bold text-white flex items-center justify-center gap-2 transition-all ${
                  isVerified ? 'bg-green-500' : 'bg-gray-800 hover:bg-black'
                }`}
              >
                {isVerified ? <CheckCircle /> : null}
                {isVerified ? 'Verified & Submitted' : 'Verify Information'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Register;
